insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://starlightdistillery.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);

insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Starlight Blackberry Whiskey","rar":"shelf","f":"Starlight","x":"Blackberry Whiskey","p":84.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"other","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://starlightdistillery.com/wp-content/uploads/2023/04/Blackberry-Whiskey-2024.jpg","u":"https://starlightdistillery.com/blackberry-whiskey/","pr":"Starlight","mk":"c7354e41-31c9-436e-9a80-dd71c74cf7d6"},{"n":"Starlight Carl T.","rar":"shelf","f":"Starlight","x":"Carl T.","p":92.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://starlightdistillery.com/wp-content/uploads/2023/03/Carl-T-Bourbobn-Whiskey-2024-1.jpg","u":"https://starlightdistillery.com/bourbons/carl-t-bourbon-whiskey/","pr":"Starlight","mk":"c7354e41-31c9-436e-9a80-dd71c74cf7d6"},{"n":"Starlight Peach Whiskey","rar":"shelf","f":"Starlight","x":"Peach Whiskey","p":84.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"other","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://starlightdistillery.com/wp-content/uploads/2025/02/Starlight-Peach-Whiskey.jpg","u":"https://starlightdistillery.com/flavored/peach-whiskey/","pr":"Starlight","mk":"c7354e41-31c9-436e-9a80-dd71c74cf7d6"},{"n":"Starlight Double Oak Old Rickhouse Rye","rar":"shelf","f":"Starlight","x":"Double Oak Old Rickhouse Rye","p":106.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"rye","mb":null,"st":"rye","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://starlightdistillery.com/wp-content/uploads/2023/04/Old-Rickhouse-Double-Oaked-Rye-Whiskey.jpg","u":"https://starlightdistillery.com/ryes/double-oak-old-rickhouse-rye-whiskey/","pr":"Starlight","mk":"c7354e41-31c9-436e-9a80-dd71c74cf7d6"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');

